<?php
namespace Zarincode\Theme\Core;
defined('ABSPATH') || exit;
final class Product_Policies {
    public static function defaults():array {return ['summary'=>'شرایط پشتیبانی و بازگشت وجه را پیش از خرید بررسی کنید. تعهد هر محصول بر اساس مشخصات همان محصول و سیاست منتشرشده فروشگاه است.','url'=>home_url('/warranty-policy/'),'faqs'=>[['id'=>'scope','question'=>'دامنه پشتیبانی چگونه مشخص می‌شود؟','answer'=>'مدت، کانال و محدوده پشتیبانی باید در مشخصات محصول یا توافق خرید درج شود. اگر موردی روشن نیست، پیش از سفارش از فروشنده بپرسید.'],['id'=>'compatibility','question'=>'چگونه از سازگاری محصول مطمئن شوم؟','answer'=>'پیش‌نیازها و نسخه‌های پشتیبانی‌شده را با محیط خود مقایسه کنید و موارد اختصاصی را پیش از خرید مطرح کنید.']]];}
    public static function sanitize($raw):array {
        if(!is_array($raw))$raw=[];$seen=[];$out=['summary'=>wp_kses_post(is_string($raw['summary']??null)?$raw['summary']:''),'url'=>Social_Manager::url($raw['url']??''),'faqs'=>[]];
        foreach(array_slice(is_array($raw['faqs']??null)?$raw['faqs']:[],0,40) as $row){if(!is_array($row))continue;$q=sanitize_text_field(is_scalar($row['question']??null)?$row['question']:'');$a=wp_kses_post(is_string($row['answer']??null)?$row['answer']:'');if($q!==''&&$a!==''){$key=sanitize_key(is_scalar($row['id']??null)?$row['id']:'');if(!$key||isset($seen[$key]))$key=wp_generate_uuid4();$seen[$key]=true;$out['faqs'][]=['id'=>$key,'question'=>$q,'answer'=>$a];}}return $out;
    }
    public static function boot():void {
        add_action('admin_menu',static function(){add_submenu_page(null,'سیاست‌ها و پرسش‌های محصول','گارانتی و پرسش‌های محصول','manage_options','zarincode-product-policies',[self::class,'page']);});
        add_action('add_meta_boxes_product',static function(){add_meta_box('zc-product-policies','زرین کد — گارانتی و پرسش‌های این محصول',[self::class,'box'],'product','normal','default');});
        add_action('admin_enqueue_scripts',static function($hook){$screen=get_current_screen();if(strpos($hook,'zarincode-product-policies')!==false||Admin_Hub::selected()==='policies'||$screen&&$screen->post_type==='product')wp_enqueue_script('zc-policy-manager',get_template_directory_uri().'/assets/js/policy-manager.js',[],ZARINCODE_VERSION,true);});
        add_action('save_post_product',static function($id){if(wp_is_post_revision($id)||defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE||!current_user_can('edit_post',$id)||!isset($_POST['zc_product_policies_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['zc_product_policies_nonce'])),'zc_product_policies_'.$id))return;
            $change=wp_unslash($_POST['zc_product_changelog']??'');update_post_meta($id,'_zc_product_changelog',is_string($change)?wp_kses_post($change):'');
            $mode=sanitize_key(wp_unslash($_POST['zc_policy_mode']??'inherit'));update_post_meta($id,'_zc_policy_mode',in_array($mode,['inherit','custom','hide'],true)?$mode:'inherit');update_post_meta($id,'_zc_product_policies',self::sanitize(wp_unslash($_POST['zc_policy']??[])));
        });
    }
    public static function get(int $id):array {$mode=get_post_meta($id,'_zc_policy_mode',true);if($mode==='hide')return [];return self::sanitize($mode==='custom'?get_post_meta($id,'_zc_product_policies',true):get_option('zarincode_product_policies',self::defaults()));}
    public static function row(array $row,$index):void {
        $name='zc_policy[faqs]['.$index.']';echo '<fieldset class="zc-policy-row" style="margin:12px 0;padding:12px;border:1px solid #ccd0d4"><input type="hidden" name="'.esc_attr($name).'[id]" value="'.esc_attr($row['id']??wp_generate_uuid4()).'"><p><label>پرسش <input class="widefat" name="'.esc_attr($name).'[question]" value="'.esc_attr($row['question']??'').'"></label></p><p><label>پاسخ <textarea class="widefat" rows="3" name="'.esc_attr($name).'[answer]">'.esc_textarea($row['answer']??'').'</textarea></label></p><button class="button zc-policy-up" type="button">↑ جابه‌جایی بالا</button> <button class="button zc-policy-remove" type="button">حذف پرسش</button></fieldset>';
    }
    public static function fields(array $data):void {
        echo '<div class="zc-policy-editor"><p><label>توضیح گارانتی و پشتیبانی <textarea class="widefat" rows="4" name="zc_policy[summary]">'.esc_textarea($data['summary']??'').'</textarea></label></p><p><label>پیوند سیاست کامل <input dir="ltr" class="widefat" name="zc_policy[url]" value="'.esc_attr($data['url']??'').'"></label></p><div class="zc-policy-list">';foreach($data['faqs']??[] as $i=>$row)self::row($row,$i);echo '</div><template class="zc-policy-template">';self::row([],'__INDEX__');echo '</template><button class="button zc-policy-add" type="button">افزودن پرسش</button></div>';
    }
    public static function box($post):void {wp_nonce_field('zc_product_policies_'.$post->ID,'zc_product_policies_nonce');$mode=get_post_meta($post->ID,'_zc_policy_mode',true)?:'inherit';echo '<p><label>محتوا <select name="zc_policy_mode">';foreach(['inherit'=>'پیش‌فرض مشترک فروشگاه','custom'=>'محتوای اختصاصی این محصول','hide'=>'پنهان در این محصول'] as $k=>$v)echo '<option value="'.$k.'" '.selected($mode,$k,false).'>'.$v.'</option>';echo '</select></label></p><p>پیش‌فرض مشترک از نمایش ← گارانتی و پرسش‌های محصول مدیریت می‌شود. تغییر حالت، محتوای اختصاصی قبلی را حذف نمی‌کند.</p>';self::fields(self::sanitize(get_post_meta($post->ID,'_zc_product_policies',true)));echo '<p><label>تاریخچه تغییرات (خالی = پنهان)<textarea class="widefat" rows="5" name="zc_product_changelog">'.esc_textarea(get_post_meta($post->ID,'_zc_product_changelog',true)).'</textarea></label></p>';}
    public static function page():void {if(!current_user_can('manage_options'))return;if(isset($_POST['zc_policy_save'])){check_admin_referer('zc_shared_policy');update_option('zarincode_product_policies',self::sanitize(wp_unslash($_POST['zc_policy']??[])),false);echo '<div class="notice notice-success"><p>سیاست مشترک ذخیره شد.</p></div>';}echo '<div class="wrap"><h1>گارانتی و پرسش‌های مشترک محصولات</h1><p>این متن فقط روی محصولات در حالت «پیش‌فرض مشترک» نمایش داده می‌شود. سیاست واقعی خود را درج کنید؛ ضمانت یا مدت پشتیبانی ساختگی تولید نمی‌شود.</p><form method="post">';wp_nonce_field('zc_shared_policy');self::fields(self::sanitize(get_option('zarincode_product_policies',self::defaults())));submit_button('ذخیره سیاست مشترک','primary','zc_policy_save');echo '</form></div>';}
    public static function render(int $id):void {$p=self::get($id);if(!$p)return;echo '<section class="zc-product-policy"><div class="zc-policy-heading"><span>شفافیت پیش از خرید</span><h3>گارانتی، پشتیبانی و پرسش‌های شما</h3></div>';if($p['summary'])echo '<div class="zc-policy-summary">'.wpautop($p['summary']).'</div>';if($p['url'])echo '<a class="zc-policy-link" href="'.esc_url($p['url']).'">مطالعه سیاست کامل ↗</a>';foreach($p['faqs'] as $i=>$row)echo '<details class="zc-policy-question"><summary><span>'.esc_html(sprintf('%02d',$i+1)).'</span>'.esc_html($row['question']).'</summary><div>'.wpautop($row['answer']).'</div></details>';echo '</section>';}
}
